<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { platformApi } from '../api'; import PageHeader from '../components/PageHeader.vue'; import ResourceState from '../components/ResourceState.vue'; import type { ProtocolSummary } from '../types'
const rows = ref<ProtocolSummary[]>([]); const loading = ref(true); const error = ref(''); onMounted(async () => { try { rows.value = await platformApi.protocols() } catch (cause) { error.value = String(cause) } finally { loading.value = false } })
</script>
<template><main class="content"><PageHeader eyebrow="Observe" title="Protocol exposure" description="Inspect every adapter attached to each logical device without moving state ownership out of StateStore." /><ResourceState :loading="loading" :error="error" :empty="rows.length === 0"><div class="list-panel"><div v-for="row in rows" :key="row.deviceId" class="protocol-row"><strong>{{ row.deviceId }}</strong><div class="protocol-pills"><span v-for="protocol in row.configured" :key="protocol.name" :class="{ online: protocol.running }">{{ protocol.name }} · {{ protocol.running ? 'online' : 'offline' }}</span><span v-for="binding in row.reserved" :key="`${binding.name}-${binding.port}`">{{ binding.name }} : {{ binding.port }}</span></div></div></div></ResourceState></main></template>
